async function requireRegularFile(targetPath, statFile) {
    let fileStats;
    try {
        fileStats = await statFile(targetPath);
    } catch {
        throw localFileLinkError(INVALID_LOCAL_FILE_LINK_ERROR, `Local file link target does not exist: ${targetPath}`);
    }
