    configService.init({ desktopConfig })
    initDefaultGithubAuthService(githubAuthService)
    initDefaultSentryConnectionService(sentryConnectionService)
    openFilesService.init({ actionService, agentInstructionsService, dataService })
    initDefaultJsonDataService()
    jsonDataService.removeEventListener('invalidated', closeInvalidatedJsonPopup)
    jsonDataService.addEventListener('invalidated', closeInvalidatedJsonPopup)
    projectPersistenceService.init({ actionService, dataService, openFilesService })
    cardMarkdownDataSource.init(dataService)
    instructionMarkdownDataSource.init(dataService)
    actionMarkdownDataSource.init(actionService)
    actionRunRegistry.start()
    actionRunSettingsService.init(dataService)
    activeScheduleService.start()
    codexCliUpdateService.start()
    claudeRateLimitService.start()
    codexRateLimitService.start()
    sentryImportService.start()
    keyboardShortcutService.start()
}

/** The account each agent remembers in the desktop selection; a missing one means the initial account. */
function selectedAgentAccountIds() {
    const { settingsByAgent } = configService.get('desktop.agentSelection')

    return Object.fromEntries(Object.entries(settingsByAgent).map(([agent, { accountId }]) => [agent, accountId]))
}

const DEFAULT_DEPENDENCIES: ApplicationStartupDependencies = {
    getGithubAccessToken: () => githubAuthService.getAccessToken(),
    initializeAgentCapabilities: () => agentCapabilitiesService.initialize(),
    refreshStartupModelCatalogs: () => agentCapabilitiesService.refreshStartupCatalogs(
        mergeAgentProfiles(configService.get('desktop.agentProfiles')),
        selectedAgentAccountIds(),
    ),
    initializeServices,
    openStartupProject: (rootPath) => projectOpenFlowService.openStartupProject(rootPath),
    readStartupProjectPath: () => getElectronDataBridge()?.getStartupProjectPath?.() ?? null,
    restoreGithubSession: () => githubAuthService.restoreSession(),
    restoreLastProject: (accessToken) => projectSessionService.restoreLastProject(accessToken),
}

/** Initializes renderer services and restores root project data once per application run. */
export class ApplicationStartupService extends EventTarget {
    private readonly dependencies: ApplicationStartupDependencies
    private snapshot = INITIAL_SNAPSHOT
    private startupPromise: Promise<void> | null = null

    constructor(dependencies: ApplicationStartupDependencies = DEFAULT_DEPENDENCIES) {
        super()
        this.dependencies = dependencies
        register('applicationStartupService', this)
    }

    getSnapshot() {
        return this.snapshot
    }

    start() {
        if (!this.startupPromise) this.startupPromise = this.runStartup()

        return this.startupPromise
    }

    private async runStartup() {
        try {
            this.dependencies.initializeServices()
            await Promise.all([
                this.dependencies.restoreGithubSession(),
                this.dependencies.initializeAgentCapabilities(),
            ])
            const resolution = await this.openInitialProject()
            await this.dependencies.refreshStartupModelCatalogs()
            this.setSnapshot({ error: null, phase: 'ready', projectOpenResolution: resolution })
        } catch (error) {
            const message = isProjectLoadErrorReported(error)
                ? null
                : error instanceof Error ? error.message : 'Startup failed'
            this.setSnapshot({ error: message, phase: 'ready', projectOpenResolution: null })
        }
    }

    /** The command-line folder wins over the last project; the open flow service shows its own dialogs. */
    private async openInitialProject() {
        const startupProjectPath = this.dependencies.readStartupProjectPath()
        if (!startupProjectPath) {
            try {
                return await this.dependencies.restoreLastProject(this.dependencies.getGithubAccessToken())
            } catch (error) {
                if (isRemoteControlConnectionError(error)) return null

                throw error
            }
        }

        await this.dependencies.openStartupProject(startupProjectPath)

        return null
    }

    private setSnapshot(snapshot: ApplicationStartupSnapshot) {
        this.snapshot = snapshot
        this.dispatchEvent(new CustomEvent<ApplicationStartupSnapshot>('changed', { detail: snapshot }))
    }
}

